// @generated by:gauntlet run:godseye-local-hermes-chat
import { createHash, randomUUID } from "node:crypto";
import { schema } from "@godseye/store";
import { eq } from "drizzle-orm";
import { afterEach, beforeEach, describe, expect, it } from "vitest";
import { type AgentsFixture, agentsFixture, controlled } from "./helpers/agents-fixture.js";

describe("owner-bound durable Hermes conversations", () => {
  let f: AgentsFixture;
  beforeEach(async () => {
    f = await agentsFixture();
  });
  afterEach(async () => {
    await f.store.close();
  });
  const chat = () => f.infrastructure.agents;
  async function create() {
    const profile = await f.create();
    const detail = await chat().chatCreate(
      f.freshOwner(),
      {
        profileId: profile.id,
        expectedRevision: profile.revision,
        title: "Private scoped chat",
      },
      randomUUID(),
    );
    return { profile, detail, id: detail.conversation.id };
  }
  async function send(id: string, input = "First private question", key = randomUUID()) {
    const current = await chat().chatDetail(f.freshOwner(), id);
    return chat().chatSend(
      f.freshOwner(),
      id,
      {
        input,
        expectedRevision: current.conversation.revision,
      },
      key,
    );
  }

  it("T-AC-741 creates and replays one conversation in the exact profile scope", async () => {
    const profile = await f.create(),
      key = randomUUID();
    const input = {
      profileId: profile.id,
      expectedRevision: profile.revision,
      title: "A private thread",
    };
    const first = await chat().chatCreate(f.freshOwner(), input, key);
    expect(await chat().chatCreate(f.freshOwner(), input, key)).toEqual(first);
    expect(first.conversation).toMatchObject({
      profileId: profile.id,
      projectId: f.project.id,
      environmentId: f.development.id,
      profileRevision: profile.revision,
    });
    expect((await chat().chatList(f.freshOwner())).conversations).toHaveLength(1);
    await expect(
      chat().chatCreate(f.freshOwner(), { ...input, title: "Changed" }, key),
    ).rejects.toMatchObject({ status: 409 });
  });

  it("T-AC-741 refuses service access to conversation content and mutation", async () => {
    const { id } = await create();
    const service = {
      ...f.freshOwner(),
      id: "agent",
      kind: "service" as const,
      projectIds: [f.project.id],
    };
    await expect(chat().chatList(service)).rejects.toMatchObject({ status: 403 });
    await expect(chat().chatDetail(service, id)).rejects.toMatchObject({ status: 403 });
    await expect(chat().chatEvents(service, id, 0)).rejects.toMatchObject({ status: 403 });
    await expect(
      chat().chatSend(service, id, { input: "Unauthorized", expectedRevision: 0 }, randomUUID()),
    ).rejects.toMatchObject({ status: 403 });
  });

  it("T-AC-742 commits one Foundation-backed turn and refuses duplicate conflicting input", async () => {
    const { id } = await create(),
      key = randomUUID();
    const before = await chat().chatDetail(f.freshOwner(), id);
    const input = { input: "One explicit request", expectedRevision: before.conversation.revision };
    const first = await chat().chatSend(f.freshOwner(), id, input, key);
    expect(await chat().chatSend(f.freshOwner(), id, input, key)).toEqual(first);
    expect(first.turns).toHaveLength(1);
    expect(first.turns[0]?.task.runId).toBeTruthy();
    expect(
      (await f.infrastructure.foundation.getBudget(f.freshOwner(), f.project.id)).reservedMicros,
    ).toBe(f.profileInput.limits.maxCostMicros);
    await expect(
      chat().chatSend(f.freshOwner(), id, { ...input, input: "Changed request" }, key),
    ).rejects.toMatchObject({ status: 409 });
    expect(f.provider.submissions).toHaveLength(0);
  });

  it("T-AC-742 assembles only ordered successful context and bounds retained history", async () => {
    const { id } = await create();
    for (let index = 0; index < 4; index++) {
      f.provider.inspectScript = async (request) => ({
        state: "succeeded",
        providerRunId: request.providerRunId,
        output: `Assistant answer ${index}`,
        stopped: true,
      });
      await send(id, `User question ${index}`);
      await f.work();
    }
    const request = f.provider.submissions.at(-1);
    expect(request?.conversation?.id).toBe(id);
    expect(request?.conversation?.history).toEqual([
      { role: "user", content: "User question 1" },
      { role: "assistant", content: "Assistant answer 1" },
      { role: "user", content: "User question 2" },
      { role: "assistant", content: "Assistant answer 2" },
    ]);
    expect((await chat().chatDetail(f.freshOwner(), id)).turns.at(-1)?.omittedTurns).toBe(1);
  });

  it("T-AC-742 refuses a new explicit turn while its predecessor remains unknown", async () => {
    const { id } = await create();
    f.provider.submitScript = async (request) => ({
      state: "unknown",
      providerRunId: `provider-${request.taskId}`,
      stopped: false,
    });
    await send(id);
    await f.work();
    await expect(send(id, "Do not replay unknown work")).rejects.toMatchObject({ status: 409 });
    expect(f.provider.submissions).toHaveLength(1);
  });

  it("T-AC-744 exposes durable ordered partial progress before provider completion without replay", async () => {
    const { id } = await create(),
      entered = controlled<void>(),
      release = controlled<void>();
    f.provider.submitScript = async (request, context) => {
      await context?.onEvent?.({
        type: "text.delta",
        sequence: 0,
        providerRunId: `provider-${request.taskId}`,
        text: "Visible partial ",
      });
      entered.resolve();
      await release.promise;
      return {
        state: "succeeded",
        providerRunId: `provider-${request.taskId}`,
        output: "Visible partial complete",
        stopped: true,
      };
    };
    await send(id);
    const work = f.work();
    try {
      await entered.promise;
      const partial = await chat().chatDetail(f.freshOwner(), id);
      expect(partial.turns[0]).toMatchObject({
        partialText: "Visible partial ",
        task: { output: null },
      });
      const events = await chat().chatEvents(f.freshOwner(), id, 0);
      expect(
        events.events.some(
          (event) => event.type === "text.delta" && event.text === "Visible partial ",
        ),
      ).toBe(true);
      const resumed = await f.build().agents.chatEvents(f.freshOwner(), id, events.cursor);
      expect(resumed.events).toEqual([]);
      expect(f.provider.submissions).toHaveLength(1);
    } finally {
      release.resolve();
      await work;
    }
  });

  it("T-AC-746 suppresses partial text emitted after environment revocation", async () => {
    const { id } = await create();
    f.provider.submitScript = async (request, context) => {
      await f.store.db
        .update(schema.environments)
        .set({ recoveryHold: true })
        .where(eq(schema.environments.id, f.development.id));
      await context?.onEvent?.({
        type: "text.delta",
        sequence: 0,
        providerRunId: `provider-${request.taskId}`,
        text: "Revoked private output",
      });
      return {
        state: "succeeded",
        providerRunId: `provider-${request.taskId}`,
        output: "Revoked private output",
        stopped: true,
      };
    };
    await send(id);
    await f.work();
    const turns = await f.store.db
      .select()
      .from(schema.agentChatTurns)
      .where(eq(schema.agentChatTurns.conversationId, id));
    expect(turns[0]?.partialText).not.toContain("Revoked private output");
    if (!turns[0]) throw new Error("Expected a retained revoked turn");
    expect((await f.detail(turns[0].taskId)).task.output).toBeNull();
  });

  it("T-AC-747 extracts immutable exact-byte artifacts only from a successful scoped response", async () => {
    const { id } = await create(),
      content = "# Draft\nRésumé 😀\n";
    f.provider.inspectScript = async (request) => ({
      state: "succeeded",
      providerRunId: request.providerRunId,
      output:
        "A draft\n```godseye-output-v1\n" +
        JSON.stringify({
          type: "artifact",
          name: "draft.md",
          mediaType: "text/markdown",
          content,
        }) +
        "\n```",
      stopped: true,
    });
    await send(id);
    await f.work();
    const detail = await chat().chatDetail(f.freshOwner(), id),
      artifact = detail.artifacts[0];
    expect(artifact).toMatchObject({
      conversationId: id,
      content,
      bytes: Buffer.byteLength(content),
      sha256: createHash("sha256").update(content).digest("hex"),
    });
    if (!artifact) throw new Error("Expected a draft artifact");
    expect(artifact.name).toMatch(/^draft-[a-f0-9-]+\.md$/);
    expect(await chat().chatArtifact(f.freshOwner(), artifact.id)).toEqual(artifact);
    const service = { ...f.freshOwner(), kind: "service" as const, projectIds: [f.project.id] };
    await expect(chat().chatArtifact(service, artifact.id)).rejects.toMatchObject({ status: 403 });
  });

  it("T-AC-747 refuses unsafe artifact names and oversized UTF-8 content", async () => {
    const { id } = await create();
    for (const artifact of [
      { name: "../escape.md", content: "No path traversal" },
      { name: "C:\\outside.txt", content: "No absolute path" },
      { name: "header\r\nInjected.txt", content: "No header injection" },
      { name: "large.md", content: "😀".repeat(4200) },
    ]) {
      f.provider.inspectScript = async (request) => ({
        state: "succeeded",
        providerRunId: request.providerRunId,
        output:
          "```godseye-output-v1\n" +
          JSON.stringify({ type: "artifact", mediaType: "text/plain", ...artifact }) +
          "\n```",
        stopped: true,
      });
      await send(id);
      await f.work();
    }
    expect((await chat().chatDetail(f.freshOwner(), id)).artifacts).toEqual([]);
  });

  it("T-AC-751 keeps private questions, answers and artifact content out of audit", async () => {
    const { id } = await create();
    f.provider.inspectScript = async (request) => ({
      state: "succeeded",
      providerRunId: request.providerRunId,
      output: "Unique private response marker",
      stopped: true,
    });
    await send(id, "Unique private question marker");
    await f.work();
    const audit = JSON.stringify(await f.infrastructure.foundation.exportAudit(f.freshOwner()));
    expect(audit).not.toContain("Unique private question marker");
    expect(audit).not.toContain("Unique private response marker");
  });

  it("T-AC-741 preserves owner history after profile reconfiguration while refusing new turns under the old policy", async () => {
    const { id, profile } = await create();
    await send(id, "Retain this historical question");
    await f.work();
    const before = await chat().chatDetail(f.freshOwner(), id);
    await chat().configureProfile(
      f.freshOwner(),
      profile.id,
      {
        expectedRevision: profile.revision,
        expectedProjectRevision: f.project.revision,
        expectedEnvironmentRevision: f.development.revision,
        model: profile.model,
        limits: { ...profile.limits, maxOutputTokens: 512 },
      },
      randomUUID(),
    );
    const after = await chat().chatDetail(f.freshOwner(), id);
    expect(after.turns).toEqual(before.turns);
    expect((await chat().chatEvents(f.freshOwner(), id, 0)).events.length).toBeGreaterThan(0);
    await expect(send(id, "Do not extend stale policy")).rejects.toMatchObject({ status: 409 });
    expect(f.provider.submissions).toHaveLength(1);
  });

  it("T-AC-747 detects changed stored artifact bytes before returning a download", async () => {
    const { id } = await create();
    f.provider.inspectScript = async (request) => ({
      state: "succeeded",
      providerRunId: request.providerRunId,
      stopped: true,
      output:
        "```godseye-output-v1\n" +
        JSON.stringify({
          type: "artifact",
          name: "safe.txt",
          mediaType: "text/plain",
          content: "Original immutable content",
        }) +
        "\n```",
    });
    await send(id);
    await f.work();
    const artifact = (await chat().chatDetail(f.freshOwner(), id)).artifacts[0];
    if (!artifact) throw new Error("Expected an immutable artifact");
    await f.store.db
      .update(schema.agentChatArtifacts)
      .set({ data: { ...artifact, content: "Changed bytes" } })
      .where(eq(schema.agentChatArtifacts.id, artifact.id));
    await expect(chat().chatArtifact(f.freshOwner(), artifact.id)).rejects.toMatchObject({
      code: "JOURNAL_INCONSISTENT",
      status: 500,
    });
  });

  it("T-AC-744 resets expired and future cursors while retaining exactly the bounded ordered suffix", async () => {
    const { id } = await create();
    f.provider.submitScript = async (request, context) => {
      for (let sequence = 0; sequence < 260; sequence++)
        await context?.onEvent?.({
          type: "text.delta",
          sequence,
          providerRunId: `provider-${request.taskId}`,
          text: "x",
        });
      return {
        state: "succeeded",
        providerRunId: `provider-${request.taskId}`,
        output: "x".repeat(260),
        stopped: true,
      };
    };
    await send(id);
    await f.work();
    const gap = await chat().chatEvents(f.freshOwner(), id, 0);
    expect(gap.reset).toBe(true);
    expect(gap.events).toEqual([]);
    const boundary = await chat().chatEvents(f.freshOwner(), id, gap.cursor - 256);
    expect(boundary.reset).toBe(false);
    expect(boundary.events).toHaveLength(256);
    expect(boundary.events.map((event) => event.cursor)).toEqual(
      Array.from({ length: 256 }, (_value, index) => gap.cursor - 255 + index),
    );
    expect(await chat().chatEvents(f.freshOwner(), id, gap.cursor + 1)).toMatchObject({
      reset: true,
      cursor: gap.cursor,
      events: [],
    });
    expect(f.provider.submissions).toHaveLength(1);
  });
});
